<!-- Benchmark app: Svelte 5 (runes). Compiled ahead of time by the Svelte compiler with fragments: "tree"
     (tools/gen-bench.mjs → svelte.gen.js): the DOM is built with createElement, no HTML strings (Trusted Types). -->
<script>
